def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Endgame: last two rounds
    if n == 99:
        return 'D'
    if n == 98:
        # If opponent has ever defected, defect; otherwise cooperate
        for h in history:
            if h[1] == 'D':
                return 'D'
        return 'C'

    # Mid-game: Tit-for-Tat with break-spiral
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    # Break mutual defection spiral
    if n >= 2 and last_my == 'D' and last_op == 'D' and my[-2] == 'D' and op[-2] == 'D':
        return 'C'

    # Retaliate if opponent just defected, otherwise cooperate
    if last_op == 'D':
        return 'D'
    return 'C'
